'use strict';

/* Folhas de efeito.
 *
 * Cada familia e uma sequencia de 4 quadros lida pela FRACAO DE VIDA do
 * efeito, nao por um timer proprio: assim um respingo de 0,24s e um
 * desmoronamento de 0,5s usam a mesma arte e ainda terminam junto com a
 * propria duracao.
 *
 *   aditiva  fogo, gelo e arcano sao luz. Desenhados com 'lighter', o preto
 *            da arte soma zero e o recorte sai de graca -- sem alfa, sem
 *            halo, e o efeito clareia o que esta embaixo, que e o que luz faz.
 *
 *   recorte  detrito e pedra e madeira. Materia opaca somada viraria entulho
 *            fosforescente, entao esse vem com alfa e desenha normal.
 */

const VFX = {
  fogo: {
    modo: 'aditiva',
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  gelo: {
    modo: 'aditiva',
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  arcano: {
    modo: 'aditiva',
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  },
  detrito: {
    modo: 'recorte',
    frames: [
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,',
      'data:image/png;base64,'
    ]
  }
};

const VFXSheet = {
  load() {
    for (const nome of Object.keys(VFX)) {
      const set = VFX[nome];
      set.images = set.frames.map(src => { const i = new Image(); i.src = src; return i; });
    }
  },

  /* k e a vida restante normalizada (1 no nascimento, 0 na morte). */
  quadro(nome, k) {
    const set = VFX[nome];
    if (!set || !set.images) return null;
    const n = set.images.length;
    let i = Math.floor((1 - k) * n);
    if (i < 0) i = 0;
    if (i >= n) i = n - 1;
    const img = set.images[i];
    return img.complete && img.naturalWidth ? img : null;
  },

  aditiva(nome) {
    const set = VFX[nome];
    return !!set && set.modo === 'aditiva';
  }
};
